    if (s(r.pause) !== '') { continue; }
    if (keep[s(r.startup).toLowerCase()]) { continue; }           // still on-mandate
    if (!r.row_number) { throw new Error('ABORT: missing row_number'); }
    out.push({ json: { row_number: Number(r.row_number), deal_id: s(r.deal_id), investor: inv, startup: s(r.startup) } });
  }
}
if (out.length === 0) { return []; }
if (out.length > 80) { throw new Error('ABORT: ' + out.length + ' deletions exceeds guard of 80'); }
out.sort(function (a, b) { return b.json.row_number - a.json.row_number; });
return out;

