const EMAIL = { 'Zeren Capital': 'sidhi.dalmia@zerencapital.com', 'a99 VC': 'Khushi@a99.vc', 'DSG Consumer Partners': 'pshirali@dsgcp.com' };
const M = {"Zeren Capital":[["Alt F Coworking","Chaman",80],["Bon Cuisine","Aditya",80],["DACBY","Chaman",80],["EosNox","Shradha",80],["Flyment","Chaman",80],["Healthy Master","Aditya",80],["LearningPad","Aditya",80],["MentorCloud","Shradha",80],["MindWox","Akansha",80],["Orbo AI","Shradha",80],["Spintly","Shradha",80],["Talent Recruit","Akansha",80],["Ulai","Shradha",80]],"a99 VC":[["Alt F Coworking","Chaman",100],["Bon Cuisine","Aditya",85],["CLIKD","Aditya",85],["Caffena Coffee","Aditya",85],["DACBY","Chaman",85],["EkoSight","Chaman",85],["Ela Greens","Chaman",85],["Flyment","Chaman",85],["GroCliq","Akansha",85],["Healthy Master","Aditya",85],["LUSTR","Aditya",85],["LearningPad","Aditya",85],["Lex Protector","Akansha",85],["Luxova","Aditya",85],["MentorCloud","Shradha",85],["My Soul","Aditya",85],["Starz AI","Akansha",85],["Sugar's Daddy","Aditya",85],["Talent Recruit","Akansha",85],["Ulai","Shradha",85],["VOLD Energy","Aditya",85],["YUNO","Aditya",85]],"DSG Consumer Partners":[["Bon Cuisine","Aditya",100],["Caffena Coffee","Aditya",100],["Chayan Karo","Shradha",100],["DACBY","Chaman",100],["Fydo","Shradha",100],["Healthy Master","Aditya",100],["LUSTR","Aditya",100],["Luxova","Aditya",100],["My Soul","Aditya",100],["Orbo AI","Shradha",100],["Sahaj","Shradha",100],["Sugar's Daddy","Aditya",100],["SureChain","Shradha",100],["VOLD Energy","Aditya",100],["Xproguard","Akansha",100],["YUNO","Aditya",100]]};

function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

const seen = {};
for (const r of rows) { seen[s(r.startup).toLowerCase() + '||' + s(r.investor).toLowerCase()] = true; }

let maxN = 0;
for (const r of rows) {
  const id = s(r.deal_id);
  if (id.charAt(0) === 'D') { const n = parseInt(id.slice(1), 10); if (!isNaN(n) && n > maxN) { maxN = n; } }
}
if (maxN === 0) { throw new Error('ABORT: could not determine max deal_id'); }

function weekdays(n, y, m, d) {
  const out = []; const dt = new Date(Date.UTC(y, m - 1, d));
  while (out.length < n) {
    const wd = dt.getUTCDay();
    if (wd !== 0 && wd !== 6) { out.push(dt.toISOString().slice(0, 10)); }
    dt.setUTCDate(dt.getUTCDate() + 1);
  }
  return out;
}

let n = maxN;
const out = [];
for (const inv of Object.keys(M)) {
  const keep = M[inv].filter(function (x) { return !seen[x[0].toLowerCase() + '||' + inv.toLowerCase()]; });
  const days = weekdays(Math.ceil(keep.length / 2) + 1, 2026, 9, 9);
  for (let i = 0; i < keep.length; i++) {
    n++;
    let pad = String(n);
    while (pad.length < 5) { pad = '0' + pad; }
    out.push({ json: {
      deal_id: 'D' + pad, startup: keep[i][0], owner: keep[i][1], investor: inv,
      email: EMAIL[inv], cc: '', priority: keep[i][2], deal_shared: 'No',
      next_action: 'Initial', next_due: days[Math.floor(i / 2)],
      notes: (keep[i][2] >= 85 ? 'Very High' : 'High') + ' match (' + keep[i][2] + ') - updated mandate 2026-09-08'
    }});
  }
}
if (out.length === 0) { return []; }
if (out.length > 51) { throw new Error('ABORT: ' + out.length + ' exceeds guard of 51'); }
return out;
